/**
 * Transformation challenges generated by the engine. Every target sentence is
 * produced by the tested rules, never free-form. A challenge id encodes the
 * seed and the change, so a missed challenge can be rebuilt for review.
 */
import type { FrameId } from "@/content/types";
import { build, DEFAULT_OPTIONS, type Options } from "./build";
import { seedById, seedsForFrame } from "./seeds";

export type Challenge = { id: string; source: string; target: string; instruction: string; accept: string[] };

export const CHANGES: { label: string; o: Partial<Options> }[] = [
  { label: "Make it negative.", o: { polarity: "negative" } },
  { label: "Make it a question.", o: { mood: "question" } },
  { label: "Put it in the past.", o: { time: "past" } },
  { label: "Put it in the future with will.", o: { time: "future" } },
  { label: "Make it a past question.", o: { time: "past", mood: "question" } },
  { label: "Make it past and negative.", o: { time: "past", polarity: "negative" } },
  { label: "Use the present perfect.", o: { aspect: "perfect" } },
  { label: "Say it's happening now (in progress).", o: { aspect: "continuous" } },
  { label: "Add should.", o: { modal: "should" } },
  { label: "Add have to.", o: { modal: "haveTo" } },
  { label: "Make it passive.", o: { voice: "passive" } },
  { label: "Make it passive and past.", o: { voice: "passive", time: "past" } },
];

/** id format: lab~<frame>~<seedId>~<changeIndex> */
export function challengeFromId(id: string): Challenge | null {
  const [tag, frame, seedId, ci] = id.split("~");
  if (tag !== "lab") return null;
  const seed = seedById(seedId);
  const change = CHANGES[Number(ci)];
  if (!seed || !change) return null;
  const base: Options = { ...DEFAULT_OPTIONS, voice: frame === "passive" && !change.o.voice ? "passive" : "active" };
  const src = build(seed, base);
  const tgtO = { ...base, ...change.o };
  const tgt = build(seed, tgtO);
  const tgtC = build(seed, { ...tgtO, contract: true });
  if (!src.ok || !tgt.ok || src.sentence === tgt.sentence) return null;
  return { id, source: src.sentence, target: tgt.sentence, instruction: change.label, accept: [tgt.sentence, ...(tgtC.ok ? [tgtC.sentence] : [])] };
}

export function randomChallenge(frame: FrameId, avoid?: string, rand = Math.random): Challenge {
  const pool = seedsForFrame(frame);
  for (let tries = 0; tries < 300; tries++) {
    const seed = pool[Math.floor(rand() * pool.length)];
    const ci = Math.floor(rand() * CHANGES.length);
    const id = `lab~${frame}~${seed.id}~${ci}`;
    if (id === avoid) continue;
    const c = challengeFromId(id);
    if (c) return c;
  }
  return challengeFromId(`lab~actions~ac-work~0`)!;
}
